+              <button type="submit">Submit request</button>
+            </form>
+          </section>
+        `;
+      }
+
+      function App() {
+        return `
+          <header class="site-header">
+            <div class="page-shell">
+              <a class="brand" href="/" aria-label="Acme Support home">
+                <span class="brand-mark" aria-hidden="true">A</span>
+                <span>Acme Support</span>
+              </a>
+            </div>
+          </header>
+          <main id="main-content">
+            <div class="page-shell support-layout">
+              <section aria-labelledby="page-title">
+                <p class="eyebrow">Support center</p>
+                <h1 id="page-title">How can we help?</h1>
+                <p class="intro">
+                  Tell us how to reach you and a support specialist will follow up with
+                  clear next steps.
+                </p>
+              </section>
+              ${ContactForm()}
+            </div>
+          </main>
+          <footer class="site-footer">
+            <div class="page-shell">Response times are typically within one business day.</div>
+          </footer>
+        `;
+      }
+
+      function setFieldValidity(input, showErrors) {
+        const field = fields.find((item) => item.id === input.id);
+        const errorElement = document.getElementById(`${input.id}-error`);
+        const isValid = input.validity.valid;
+
+        input.setAttribute("aria-invalid", showErrors && !isValid ? "true" : "false");
+
+        if (showErrors && !isValid) {
+          errorElement.textContent = field.error;
+          errorElement.hidden = false;
+        } else {
+          errorElement.textContent = "";
+          errorElement.hidden = true;
+        }
+
+        return isValid;
+      }
+
+      function attachFormBehavior() {
+        const form = document.getElementById("contact-form");
+        const status = document.getElementById("form-status");
+        const inputs = Array.from(form.querySelectorAll("input"));
+        let hasSubmitted = false;
+
+        inputs.forEach((input) => {
+          input.addEventListener("input", () => {
+            if (hasSubmitted) {
+              setFieldValidity(input, true);
+            }
+            status.textContent = "";
+          });
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          hasSubmitted = true;
+
+          const firstInvalid = inputs.find((input) => !setFieldValidity(input, true));
+
+          if (firstInvalid) {
+            status.textContent = "";
+            firstInvalid.focus();
+            return;
+          }
+
+          status.textContent = "Thanks. Your support request is ready to send.";
+          form.reset();
+          inputs.forEach((input) => setFieldValidity(input, false));
+          hasSubmitted = false;
+        });
+      }
+
+      document.getElementById("root").innerHTML = App();
+      attachFormBehavior();
+    </script>
+  </body>
+</html>
+

')

